public class SleighProgramCompilerTest : AbstractGTest {
	protected T rfail<T>(string message) {
		fail(message);
		throw new AssertionError();
	}

	protected E expect<E>/* where E : Exception */(Class<E> cls, ExceptionalCallback<E> cb) {
		try {
			cb.call();
		}
		catch (Throwable e) {
			if (!cls.isInstance(e)) {
				e.printStackTrace();
				return rfail("Expected " + cls + ". Got " + e.GetType());
			}
			return cls.cast(e);
		}
		return rfail("Expected " + cls + ". Got success");
	}

	/* @Before */
	public void setUp()
    {
		if (!Application.isInitialized()) {
			Application.initializeApplication(
				new GhidraTestApplicationLayout(new File(getTestDirectoryPath())),
				new ApplicationConfiguration());
		}
	}

	/* @Test */
	public void testGoto64BitOffset()
    {
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();
		PcodeProgram program = SleighProgramCompiler.compileProgram(language, "test",
			"goto 0x140000000;", PcodeUseropLibrary.NIL);

		assertEquals(1, program.getCode().size());
		PcodeOp branchOp = program.getCode().getFirst();
		assertEquals(PcodeOp.BRANCH, branchOp.getOpcode());
		assertNull(branchOp.getOutput());
		assertEquals(1, branchOp.getNumInputs());
		Varnode target = branchOp.getInput(0);
		assertEquals(0x140000000L, target.getOffset());
	}

	/* @Test */
	public void testCompileProgramErrLocations()
    {
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();
		DetailedSleighException exc = expect(typeof(DetailedSleighException), () => {
			PcodeProgram program =
				SleighProgramCompiler.compileProgram(language, "test", "noreg = noreg;",
					PcodeUseropLibrary.NIL);
			// Shouldn't get here, but if we do, I'd like to see the program:
			Console.Error.WriteLine(program);
		});
		PcodeLogEntry entry = Unique.assertOne(exc.getDetails());
		Location loc = entry.loc();
		assertEquals("test", loc.filename);
		assertEquals(1, loc.lineno);
		assertEquals("unknown varnode or bitrange symbol 'noreg' in expression", entry.msg());
	}

	/* @Test */
	public void testCompileExpressionErrLocations()
    {
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();
		DetailedSleighException exc = expect(typeof(DetailedSleighException), () => {
			PcodeProgram program = SleighProgramCompiler.compileExpression(language, "noreg");
			// Shouldn't get here, but if we do, I'd like to see the program:
			Console.Error.WriteLine(program);
		});
		PcodeLogEntry entry = Unique.assertOne(exc.getDetails());
		// TODO: It'd be nice if loc included a column number and token length
		Location loc = entry.loc();
		assertEquals("expression", loc.filename);
		assertEquals(1, loc.lineno);
		assertEquals("unknown varnode or bitrange symbol 'noreg' in expression", entry.msg());
	}
}
